    private PlaylistGroup activeGroup(){return librarySection.equals("created")?createdPlaylists:savedPlaylists;}
    private TextView sectionNav(){return librarySection.equals("likes")?likesNav:librarySection.equals("created")?createdNav:collectionsNav;}
    private String sectionTitle(){return librarySection.equals("created")?"创建歌单":"收藏歌单";}
    private void bindGroup(){PlaylistGroup group=activeGroup();collections.clear();collections.addAll(group.items);collectionAdapter.notifyDataSetChanged();librarySubtitle.setText(sectionTitle()+(group.total>0?" · "+group.total+" 个":""));}
    private void setLibrarySection(String section,boolean focusContent){
        pendingLibraryFocus="";librarySection=section;boolean likes=section.equals("likes");if(!likes)bindGroup();likedList.setVisibility(likes?View.VISIBLE:View.GONE);collectionGrid.setVisibility(likes?View.GONE:View.VISIBLE);if(likes)librarySubtitle.setText("最新收藏优先");
        if(music.phase.equals("ready")){if(likes&&likedTracks.isEmpty())loadLiked();else if(!likes&&activeGroup().items.isEmpty())loadCollections();}refreshTabs();if(focusContent)focusLibraryContent();
    }
    private void focusLibraryContent(){
        AbsListView target=librarySection.equals("likes")?likedList:collectionGrid;int count=target.getCount();
        if(count==0){sectionNav().requestFocusFromTouch();boolean loading=librarySection.equals("likes")?likedLoading:activeGroup().loading;pendingLibraryFocus=loading?librarySection:"";if(!loading)hint(librarySection.equals("likes")?"还没有爱心歌曲":"还没有"+sectionTitle());return;}
        pendingLibraryFocus="";int selected=target.getSelectedItemPosition();if(selected<0||selected>=count)target.setSelection(0);target.requestFocusFromTouch();panel.post(()->moveFocus());
    }
    private void loadLiked(){if(likedLoading||!likedMore||closed)return;likedLoading=true;int version=likedGeneration;music.fetch("/api/likes?offset="+likedOffset,(data,error)->{if(closed||version!=likedGeneration)return;likedLoading=false;if(error!=null){if(librarySection.equals("likes"))librarySubtitle.setText(error);return;}JSONArray list=data.optJSONArray("tracks");if(list!=null)for(int i=0;i<list.length();i++)likedTracks.add(new MusicController.Track(list.optJSONObject(i)));likedOffset=data.optInt("next");likedMore=data.optBoolean("hasMore");likedAdapter.notifyDataSetChanged();if(librarySection.equals("likes")){librarySubtitle.setText("最新收藏优先 · "+data.optInt("total")+" 首");likedList.post(()->{if(pendingLibraryFocus.equals("likes")&&page.equals("library"))focusLibraryContent();else moveFocus();});}});}
