    private TextView button(String text,Runnable action){TextView v=label(text,21,Color.WHITE,medium);v.setGravity(Gravity.CENTER);v.setFocusable(true);v.setClickable(true);v.setBackground(surface(0x0bffffff,0x1cffffff,px(26)));v.setOnClickListener(a->action.run());v.setOnFocusChangeListener((a,f)->{focus(v,f);if(f)hint(text+" · 确认选择");});v.setOnHoverListener((a,e)->{if(e.getAction()==MotionEvent.ACTION_HOVER_ENTER)a.requestFocusFromTouch();return false;});return v;}
    private boolean chosen(View v){return v==libraryNav&&(page.equals("library")||page.equals("album"))||v==searchNav&&page.equals("search")||v==nowNav&&page.equals("now")||v==songFilter&&searchType.equals("song")||v==playlistFilter&&searchType.equals("playlist")||v==likesNav&&page.equals("library")&&librarySection.equals("likes")||v==collectionsNav&&page.equals("library")&&librarySection.equals("collections")||v==createdNav&&page.equals("library")&&librarySection.equals("created");}
    private void refreshTabs(){for(TextView v:new TextView[]{libraryNav,searchNav,nowNav,songFilter,playlistFilter,likesNav,collectionsNav,createdNav})if(v!=null)v.setBackground(surface(chosen(v)?0x16ffffff:0x06ffffff,chosen(v)?0x26ffffff:0x12ffffff,px(26)));accountButton.setVisibility(page.equals("login")?View.INVISIBLE:View.VISIBLE);}
    private void focus(View v,boolean selected){if(selected&&(v==likesNav||v==collectionsNav||v==createdNav))pendingLibraryFocus="";v.animate().cancel();v.animate().scaleX(selected?1.025f:1).scaleY(selected?1.025f:1).setDuration(300).setInterpolator(glide).start();v.setBackground(surface(chosen(v)?0x16ffffff:0x06ffffff,0x16ffffff,px(26)));if(selected)moveFocus();}
    private void moveFocus(){if(closed||glassFocus==null||pageMoving)return;if(lyrics!=null&&lyrics.hasFocus()){glassFocus.hideFocus();return;}View target=getCurrentFocus();if(target instanceof AdapterView){View selected=target instanceof AbsListView?MusicListMotion.selectedView((AbsListView)target):((AdapterView<?>)target).getSelectedView();if(selected!=null)target=selected;else{glassFocus.hideFocus();return;}}if(target!=null&&target!=panel&&target.isShown())glassFocus.move(target);}
    private void show(String target,boolean animate){
        if(!music.phase.equals("ready")&&!target.equals("login"))target="login";if(target.equals(page))return;
        String previous=page;final String destination=target;FrameLayout old=pages.get(previous),next=pages.get(target);page=target;
        for(Map.Entry<String,FrameLayout> entry:pages.entrySet()){FrameLayout view=entry.getValue();view.animate().cancel();if(view!=old&&view!=next)view.setVisibility(View.GONE);}
        boolean returning=previous.equals("now")||target.equals("library")&&!previous.equals("login");float direction=returning?-1:1;
        pageMoving=animate&&android.animation.ValueAnimator.areAnimatorsEnabled();glassFocus.hideFocus();
        if(old!=null){old.setVisibility(View.VISIBLE);old.setAlpha(1);old.setTranslationX(0);if(pageMoving)old.animate().alpha(0).translationX(-direction*px(90)).setDuration(360).setInterpolator(glide).withEndAction(()->{if(!page.equals(previous)){old.setVisibility(View.GONE);old.setAlpha(1);old.setTranslationX(0);}}).start();else old.setVisibility(View.GONE);}
        next.setVisibility(View.VISIBLE);next.setAlpha(pageMoving?0:1);next.setTranslationX(pageMoving?direction*px(130):0);
        if(pageMoving)next.animate().alpha(1).translationX(0).setDuration(460).setInterpolator(glide).withEndAction(()->{if(!closed&&page.equals(destination)){pageMoving=false;moveFocus();}}).start();
        mini.setVisibility(target.equals("login")||target.equals("now")?View.GONE:View.VISIBLE);sidePreview.setVisibility(target.equals("login")||target.equals("now")?View.GONE:View.VISIBLE);if(sidePreview.getVisibility()==View.VISIBLE){sidePreview.animate().cancel();sidePreview.setAlpha(pageMoving?0:1);sidePreview.setTranslationX(pageMoving?direction*px(60):0);if(pageMoving)sidePreview.animate().alpha(1).translationX(0).setDuration(460).setInterpolator(glide).start();}
        libraryNav.setVisibility(target.equals("login")?View.INVISIBLE:View.VISIBLE);searchNav.setVisibility(libraryNav.getVisibility());nowNav.setVisibility(libraryNav.getVisibility());
        if(target.equals("now")){lyrics.start();lyrics.update();nowPlay.requestFocusFromTouch();}else{lyrics.stop();if(target.equals("library")){readyOnce=true;setLibrarySection(librarySection,false);focusLibraryContent();}else if(target.equals("album"))albumList.requestFocusFromTouch();else if(target.equals("search"))searchField.requestFocus();else retry.requestFocus();}
        refreshTabs();if(!pageMoving)panel.post(()->moveFocus());if(!target.equals("now"))ambient.setArtwork(null);else if(artworkId>=0)music.cover(artworkId,image->{if(!closed&&page.equals("now"))ambient.setArtwork(image);});hint(target.equals("now")?"进度条左右快进快退 · 返回音乐列表":target.equals("search")?"输入关键词 · 选择单曲或歌单 · 确认搜索":"选择歌单 · 最右侧再按右进入正在播放");
    }
    private void showNow(){boolean restored=music.current()==null;if(!music.restoreLast()){hint("先选择一首喜欢的音乐");return;}if(!page.equals("now"))beforeNow=page;show("now",true);if(restored)hint("确认播放 · 继续上次进度");}
